import numpy as np
from scipy.optimize import minimize

def solve_for_n(n):
    def objective(a):
        return -np.sum(a**2)

    def constraint1(a):
        return np.sum(a**3)

    # Constraint a_i <= 2/sqrt(n)
    bounds = [(-np.inf, 2.0 / np.sqrt(n)) for _ in range(n)]

    # Use multiple starting points to avoid local minima
    max_s = -1
    for _ in range(10):
        a0 = np.random.uniform(-2.0, 2.0 / np.sqrt(n), n)
        res = minimize(objective, a0, bounds=bounds, constraints={'type': 'eq', 'fun': constraint1})
        if res.success:
            max_s = max(max_s, -res.fun)

    return max_s

for n in range(1, 21):
    print(f"n={n}, max_s={solve_for_n(n)}")

import numpy as np
from scipy.optimize import minimize

def solve_for_n_refined(n):
    def objective(a):
        return -np.sum(a**2)

    def constraint1(a):
        return np.sum(a**3)

    limit = 2.0 / np.sqrt(n)
    bounds = [(-100.0, limit) for _ in range(n)] # Use a large negative number for the lower bound

    max_s = -1
    # Try several strategies for starting points
    # 1. Some elements at limit, one element to satisfy the sum
    for k in range(n):
        a0 = np.zeros(n)
        for i in range(k):
            a0[i] = limit
        # k * limit^3 + (n-k) * y^3 = 0 => y^3 = -k/n-k * limit^3
        if n - k > 0:
            y = - (k / (n - k))**(1/3) * limit
            for i in range(k, n):
                a0[i] = y
        else:
            continue

        res = minimize(objective, a0, bounds=bounds, constraints={'type': 'eq', 'fun': constraint1})
        if res.success:
            max_s = max(max_s, -res.fun)

    # 2. Random starting points
    for _ in range(50):
        a0 = np.random.uniform(-limit, limit, n)
        res = minimize(objective, a0, bounds=bounds, constraints={'type': 'eq', 'fun': constraint1})
        if res.success:
            max_s = max(max_s, -res.fun)

    return max_s

for n in range(1, 21):
    print(f"n={n}, max_s={solve_for_n_refined(n)}")
